import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int v = sc.nextInt();
        int e = sc.nextInt();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < v; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt();
            int w = sc.nextInt();
            adj.get(u).add(w);
            adj.get(w).add(u);
        }
        int s = sc.nextInt();
        int d = sc.nextInt();
        if (s == d) { System.out.println(0); return; }
        int[] dist = new int[v];
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.add(s);
        while (!q.isEmpty()) {
            int curr = q.poll();
            if (curr == d) break;
            for (int nxt : adj.get(curr)) {
                if (dist[nxt] == -1) {
                    dist[nxt] = dist[curr] + 1;
                    q.add(nxt);
                }
            }
        }
        System.out.println(dist[d]);
    }
}

