#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Edge { int to; struct Edge *next; } Edge;

int main() {
    int v, e;
    if (scanf("%d %d", &v, &e) != 2) return 0;
    Edge **head = (Edge**)calloc(v, sizeof(Edge*));
    for (int i = 0; i < e; i++) {
        int u, w;
        scanf("%d %d", &u, &w);
        Edge *e1 = (Edge*)malloc(sizeof(Edge));
        e1->to = w; e1->next = head[u]; head[u] = e1;
        Edge *e2 = (Edge*)malloc(sizeof(Edge));
        e2->to = u; e2->next = head[w]; head[w] = e2;
    }
    int s, d;
    scanf("%d %d", &s, &d);
    if (s == d) { printf("0\n"); return 0; }
    int *dist = (int*)malloc(v * sizeof(int));
    memset(dist, -1, v * sizeof(int));
    int *q = (int*)malloc(v * sizeof(int));
    int qh = 0, qt = 0;
    dist[s] = 0;
    q[qt++] = s;
    while (qh < qt) {
        int curr = q[qh++];
        if (curr == d) break;
        for (Edge *p = head[curr]; p != NULL; p = p->next) {
            if (dist[p->to] == -1) {
                dist[p->to] = dist[curr] + 1;
                q[qt++] = p->to;
            }
        }
    }
    printf("%d\n", dist[d]);
    return 0;
}
